SELECT PRD_SN
FROM AUCTION
WHERE AUC_SN = #{auctionId}

SELECT AUC_SN
FROM AUCTION
WHERE PRD_SN = #{productId}

SELECT a.PRD_SN AS prdSn, a.AUC_SN AS aucSn, a.AUC_STATUS_CD AS aucStatusCd, aucStatus.CMM_NM AS aucStatusNm FROM AUCTION a LEFT JOIN CMM_CODE aucStatus ON aucStatus.CMM_CD = a.AUC_STATUS_CD WHERE a.PRD_SN IN
#{prdSn}
ORDER BY a.PRD_SN

mapper.update:
UPDATE BID
SET BID_TRD_METHOD_CD = #{tradeMethodCode},
    BID_DLVR_ADDR_SN = #{deliveryAddressId},
    BID_UPDT_ID = #{actor},
    BID_UPDT_DT = NOW()
WHERE AUC_SN = #{auctionId}
  AND BID_SN = #{bidId}
  AND USR_SN = #{userId}
  AND BID_STATUS_CD = 'BIDC0001'
  AND NOT (
      BID_TRD_METHOD_CD <=> #{tradeMethodCode}
      AND BID_DLVR_ADDR_SN <=> #{deliveryAddressId}
  )

UPDATE AUCTION
SET AUC_STATUS_CD = #{newStatusCode},
    AUC_UPDT_ID = #{actor},
    AUC_UPDT_DT = NOW()
WHERE AUC_SN = #{auctionId}
  AND AUC_STATUS_CD = #{expectedStatusCode}
